/*
 * amrviz - real-time view of a block-structured AMR mesh (see amrviz.h)
 *
 * Inspired by FluidX3D (Moritz Lehmann, https://github.com/ProjectPhysX/FluidX3D):
 * the controls and the on-screen status and help overlay follow its
 * interactive graphics (P pause, H help, number keys for the layers, Z for
 * the colouring, +/- and I/J/K/L for the camera, G to print the view),
 * adapted to a 2D view. No FluidX3D code is used.
 *
 * Colour maps: lookup tables (viridis by default; C cycles magma, the
 * diverging coolwarm with a range symmetric about zero, gray), generated by
 * tools/make_colormap_header.py.
 *
 * Two modes, chosen in amrviz_open:
 *
 * Render thread (default): the solver thread calls amrviz_begin_snapshot ..
 * amrviz_end_snapshot and writes only to the back buffer. amrviz_end_snapshot
 * swaps it with the pending buffer under the mutex; the render thread swaps
 * pending with its front buffer when it finds a new one. Each thread owns its
 * buffer exclusively, so the copies themselves need no locking.
 *
 * Caller's thread (macOS, or AMRVIZ_THREAD=0): Cocoa allows windows and
 * their events only on the main thread, which is the solver's. There the
 * window, the GL context and the event handling all live on the thread that
 * called amrviz_open: amrviz_end_snapshot handles the queued events and
 * draws (at most about 60 times a second), amrviz_wait_if_paused and
 * amrviz_close(1) run the event loop until the user resumes or closes. The
 * same buffers and swaps are used, all on one thread. Between snapshots the
 * window does not react, so the update interval should be short.
 *
 * GL functions are loaded through SDL_GL_GetProcAddress (no libGL link, and
 * no GL header: amrviz_gl.h declares what is used).
 */
#define _POSIX_C_SOURCE 200809L
#ifdef __APPLE__
#define _DARWIN_C_SOURCE                 /* pthread_main_np */
#endif
#include "amrviz.h"
#include "amrviz_colormaps.h"
#include "amrviz_font.h"
#include "amrviz_gl.h"

#include <SDL.h>

#include <math.h>
#include <pthread.h>
#include <stdarg.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

